import { randomUUID } from "node:crypto";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { PrismaClient } from "@/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";

const mocks = vi.hoisted(() => ({
  database: null as unknown,
  user: vi.fn(),
  gmail: vi.fn(),
  send: vi.fn(),
}));
// Production helpers use a real generated client pointed at our isolated schema.
vi.mock("@/lib/db", () => ({
  get db() {
    return mocks.database;
  },
}));
vi.mock("@/lib/session", () => ({ requireUser: mocks.user }));
vi.mock("next/cache", () => ({ revalidatePath: vi.fn() }));
vi.mock("@/lib/gmail", async (original) => ({
  ...(await original<typeof import("@/lib/gmail")>()),
  gmailForUser: mocks.gmail,
}));
import { saveTemplate, importContacts } from "@/lib/actions";
import { saveFollowUpDays } from "@/lib/launch-actions";
import { markReplied, undoReply } from "@/lib/recipient-actions";
import { createCampaign } from "@/lib/campaigns";
import { readFollowUps } from "@/lib/follow-ups";
import { countQuotaUsage } from "@/lib/delivery-usage";
import { clearCompletedHistory } from "@/lib/history";
import { deliverOne } from "@/lib/inngest";
import { requireEntitlement } from "@/lib/entitlements";
import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
import { encryptToken } from "@/lib/crypto";

describe.runIf(databaseTestsEnabled)(
  "entitlement foundation with generated Prisma client",
  () => {
    let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>;
    let db: PrismaClient;
    let userId: string;
    beforeAll(async () => {
      fixture = await createIsolatedDatabase();
      try {
        for (const migration of fixture.migrations)
          await fixture.apply(migration);
        db = new PrismaClient({
          adapter: new PrismaPg(
            { connectionString: fixture.url, max: 5 },
            { schema: fixture.schema },
          ),
        });
        mocks.database = db;
        const ownerId = randomUUID();
        const user = await db.user.create({
          data: {
            id: ownerId,
            email: `${randomUUID()}@example.test`,
            gmailAuthorized: true,
            encryptedRefreshToken: encryptToken(
              "FAKE-FOUNDATION-TOKEN",
              ownerId,
            ),
          },
        });
        userId = user.id;
        mocks.user.mockResolvedValue(user);
        mocks.gmail.mockResolvedValue({
          email: user.email,
          gmail: { users: { messages: { send: mocks.send } } },
        });
        mocks.send.mockResolvedValue({
          data: { id: "gmail-id", threadId: "gmail-thread" },
        });
      } catch (error) {
        if (db) await db.$disconnect();
        await fixture.cleanup();
        throw error;
      }
    });
    afterAll(async () => {
      if (db) await db.$disconnect();
      if (fixture) await fixture.cleanup();
    });

    it("creates UUIDs and reads/writes every new model", async () => {
      const subscription = await db.billingSubscription.create({
        data: {
          userId,
          dodoSubscriptionId: "sub",
          dodoCustomerId: "customer",
          productId: "product",
          status: "PENDING",
        },
      });
      const checkout = await db.checkoutAttempt.create({
        data: {
          userId,
          idempotencyKey: "key",
          productId: "product",
          billingCountry: "US",
          billingCurrency: "USD",
          expiresAt: new Date(Date.now() + 60000),
        },
      });
      const event = await db.billingWebhookEvent.create({
        data: {
          webhookId: "event",
          eventType: "type",
          businessId: "business",
          occurredAt: new Date(),
          normalizedData: {},
          payloadHash: "a".repeat(64),
        },
      });
      const audit = await db.adminAuditLog.create({
        data: {
          actorUserId: userId,
          targetUserId: userId,
          actorIdSnapshot: userId,
          targetIdSnapshot: userId,
          action: "SUSPENSION",
          requestId: randomUUID(),
          requestHash: "a".repeat(64),
          reason: "SUPPORT",
          before: { isSuspended: false },
          after: { isSuspended: false },
        },
      });
      const control = await db.systemControl.findUniqueOrThrow({
        where: { key: "global" },
      });
      for (const row of [
        subscription,
        checkout,
        event,
        audit,
        control,
        { id: userId },
      ])
        expect(row.id).toMatch(
          /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/,
        );
      expect(await db.billingSubscription.count({ where: { userId } })).toBe(1);
      expect(await db.checkoutAttempt.count({ where: { userId } })).toBe(1);
      expect(
        await db.billingWebhookEvent.findUnique({
          where: { webhookId: "event" },
        }),
      ).toMatchObject({ id: event.id, attempts: 0 });
      expect(
        await db.adminAuditLog.findFirst({
          where: { id: audit.id, targetUserId: userId },
        }),
      ).toMatchObject({ reason: "SUPPORT" });
      await db.$transaction(async (tx) => {
        await requireEntitlement(userId, "csvImport", tx);
      });
      await db.systemControl.update({
        where: { key: "global" },
        data: { paidGatingEnabled: true },
      });
      await expect(
        requireEntitlement(userId, "csvImport"),
      ).rejects.toMatchObject({ code: "UPGRADE_REQUIRED" });
      await db.systemControl.update({
        where: { key: "global" },
        data: { paidGatingEnabled: false },
      });
    });
    it("retains CSV, multiple templates, custom roles, reminders, worker delivery and reply marking for Free users", async () => {
      expect(await db.user.findUnique({ where: { id: userId } })).toMatchObject(
        { plan: "FREE", subscriptionStatus: "NONE", freeTemplateId: null },
      );
      const templates: string[] = [];
      for (const name of ["First", "Second"]) {
        const form = new FormData();
        Object.entries({
          name,
          subject: "Hello {{name}}",
          body: "Applying for {{role}}",
        }).forEach(([key, value]) => form.set(key, value));
        const result = await saveTemplate(form);
        expect(result.ok).toBe(true);
        templates.push(
          (await db.template.findFirstOrThrow({ where: { userId, name } })).id,
        );
      }
      expect(
        (
          await importContacts(
            "name,email,jobRole\nAda,[REDACTED_EMAIL],Unusual role\nBob,[REDACTED_EMAIL],Unusual role\nCal,[REDACTED_EMAIL],Unusual role\nDee,[REDACTED_EMAIL],Unusual role",
          )
        ).ok,
      ).toBe(true);
      const contacts = await db.contact.findMany({ where: { userId } });
      expect(contacts).toHaveLength(4);
      expect((await saveFollowUpDays(3)).ok).toBe(true);
      const campaign = await createCampaign(userId, {
        templateId: templates[1],
        recipientIds: contacts.map((c) => c.id),
        recipientRoles: Object.fromEntries(
          contacts.map((c) => [c.id, "Unusual role"]),
        ),
        attachResume: false,
        idempotencyKey: randomUUID(),
      });
      expect(campaign.count).toBe(4);
      expect(DAILY_EMAIL_LIMIT).toBe(200);
      expect(await countQuotaUsage(userId)).toBe(4);
      const send = await db.send.findFirstOrThrow({
        where: { campaignId: campaign.id, campaign: { userId } },
      });
      expect(await deliverOne(userId, send.id)).toEqual({ outcome: "done" });
      expect(mocks.send).toHaveBeenCalledOnce();
      await db.send.updateMany({
        where: { id: send.id, campaign: { userId } },
        data: { sentAt: new Date(Date.now() - 8 * 86400000) },
      });
      expect((await readFollowUps(userId, 3)).total).toBe(1);
      expect((await markReplied(send.id)).ok).toBe(true);
      expect((await readFollowUps(userId, 3)).total).toBe(0);
      expect((await undoReply(send.id)).ok).toBe(true);
      await db.send.updateMany({
        where: { id: send.id, campaign: { userId } },
        data: { sentAt: new Date() },
      });
      expect(await clearCompletedHistory(userId)).toBe(1);
      expect(await db.deliveryReceipt.count({ where: { userId } })).toBe(1);
      expect(await countQuotaUsage(userId)).toBe(4);
      // Delivery now reloads controls before claiming an attempt.
      await db.systemControl.update({
        where: { key: "global" },
        data: { sendingEnabled: false, paidGatingEnabled: true },
      });
      const queued = await db.send.findFirstOrThrow({
        where: { campaign: { userId }, status: "QUEUED" },
      });
      await db.user.update({
        where: { id: userId },
        data: { nextSendAt: null },
      });
      expect(await deliverOne(userId, queued.id)).toMatchObject({
        outcome: "done",
      });
      await db.systemControl.update({
        where: { key: "global" },
        data: { sendingEnabled: true, paidGatingEnabled: false },
      });
    });
    it("keeps the rolling 200-email limit including receipts and queued work", async () => {
      const template = await db.template.findFirstOrThrow({
        where: { userId },
      });
      const contact = await db.contact.create({
        data: {
          userId,
          name: "New",
          email: "[REDACTED_EMAIL]",
          jobRole: "Engineer",
        },
      });
      const usage = await countQuotaUsage(userId);
      await db.deliveryReceipt.createMany({
        data: Array.from({ length: 200 - usage }, (_, index) => ({
          userId,
          recipientEmail: `evidence-${index}@example.test`,
          createdAt: new Date(),
          sentAt: new Date(),
        })),
      });
      const input = {
        templateId: template.id,
        recipientIds: [contact.id],
        recipientRoles: { [contact.id]: "Engineer" },
        attachResume: false,
        idempotencyKey: randomUUID(),
      };
      await expect(createCampaign(userId, input)).rejects.toThrow(
        "200 emails per rolling 24 hours",
      );
      await db.deliveryReceipt.updateMany({
        where: { userId, recipientEmail: "[REDACTED_EMAIL]" },
        data: { sentAt: new Date(Date.now() - 86400001) },
      });
      expect((await createCampaign(userId, input)).count).toBe(1);
      expect(await countQuotaUsage(userId)).toBe(200);
    });
  },
);
